     5→/* ---------- CSS Custom Properties ---------- */
     6→:root {
     7→  --color-primary:       #1d4ed8;
     8→  --color-primary-dark:  #1e40af;
     9→  --color-primary-light: #eff6ff;
    10→  --color-accent:        #7c3aed;
    11→  --color-accent-light:  #f5f3ff;
    12→
    13→  --color-bg:            #ffffff;
    14→  --color-bg-alt:        #f8fafc;
    15→  --color-bg-dark:       #0f172a;
    16→
    17→  --color-text:          #0f172a;
    18→  --color-text-muted:    #64748b;
    19→  --color-text-light:    #94a3b8;
    20→
    21→  --color-border:        #e2e8f0;
    22→  --color-card-bg:       #ffffff;
    23→
    24→  /* publication quality colours */
    25→  --color-q1:            #065f46;
    26→  --color-q1-bg:         #d1fae5;
    27→  --color-q2:            #1e40af;
    28→  --color-q2-bg:         #dbeafe;
    29→  --color-thesis:        #6b21a8;
    30→  --color-thesis-bg:     #f3e8ff;
    31→  --color-conf:          #92400e;
    32→  --color-conf-bg:       #fef3c7;
    33→  --color-preprint:      #be185d;
    34→  --color-preprint-bg:   #fce7f3;
    35→
    36→  --font-sans:  'Inter', system-ui, -apple-system, sans-serif;
    37→  --font-serif: 'Merriweather', Georgia, 'Times New Roman', serif;
    38→
    39→  --radius-sm:   6px;
    40→  --radius-md:   12px;
    41→  --radius-lg:   20px;
    42→  --radius-full: 9999px;
    43→
    44→  --shadow-sm:  0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
    45→  --shadow-md:  0 4px 16px rgba(0,0,0,0.08), 0 2px 6px rgba(0,0,0,0.05);
    46→  --shadow-lg:  0 10px 40px rgba(0,0,0,0.10), 0 4px 12px rgba(0,0,0,0.06);
    47→
    48→  --transition: 0.22s ease;
    49→  --nav-height: 68px;
    50→}
    51→
    52→/* ---------- Reset & Base ---------- */
    53→*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    54→
    55→html { scroll-behavior: smooth; font-size: 16px; }
    56→
    57→body {
    58→  font-family: var(--font-sans);
    59→  color: var(--color-text);
    60→  background: var(--color-bg);
    61→  line-height: 1.7;
    62→  -webkit-font-smoothing: antialiased;
    63→  -moz-osx-font-smoothing: grayscale;
    64→}
    65→
    66→img { max-width: 100%; display: block; }
    67→a  { color: var(--color-primary); text-decoration: none; }
    68→a:hover { text-decoration: underline; }
    69→
    70→/* ---------- Utilities ---------- */
    71→.container {
    72→  max-width: 1080px;
    73→  margin: 0 auto;
    74→  padding: 0 24px;
    75→}
    76→
    77→.inline-link {
    78→  color: var(--color-primary);
    79→  font-weight: 500;
    80→  border-bottom: 1px solid transparent;
    81→  transition: border-color var(--transition);
    82→}
    83→.inline-link:hover { text-decoration: none; border-bottom-color: var(--color-primary); }
    84→
    85→/* ---------- Buttons ---------- */
    86→.btn {
    87→  display: inline-flex;
    88→  align-items: center;
    89→  gap: 7px;
    90→  padding: 10px 22px;
    91→  border-radius: var(--radius-full);
    92→  font-size: 0.875rem;
    93→  font-weight: 600;
    94→  cursor: pointer;
    95→  transition: background var(--transition), color var(--transition),
    96→              border-color var(--transition), transform var(--transition),
    97→              box-shadow var(--transition);
    98→  border: 2px solid transparent;
    99→  text-decoration: none !important;
   100→  white-space: nowrap;
   101→  letter-spacing: 0.01em;
   102→}
   103→.btn:active { transform: scale(0.97); }
   104→
   105→.btn-primary {
   106→  background: var(--color-primary);
   107→  color: #fff;
   108→  border-color: var(--color-primary);
   109→}
   110→.btn-primary:hover {
   111→  background: var(--color-primary-dark);
   112→  border-color: var(--color-primary-dark);
   113→  box-shadow: 0 4px 18px rgba(29,78,216,0.35);
   114→}
   115→
   116→.btn-outline {
   117→  background: transparent;
   118→  color: var(--color-primary);
   119→  border-color: var(--color-primary);
   120→}
   121→.btn-outline:hover {
   122→  background: var(--color-primary);
   123→  color: #fff;
   124→  box-shadow: 0 4px 14px rgba(29,78,216,0.25);
   125→}
   126→
   127→.btn-sm   { padding: 5px 14px; font-size: 0.8rem; }
   128→.btn-large { padding: 14px 34px; font-size: 0.95rem; }
   129→
   130→/* ---------- Navbar ---------- */
   131→.navbar {
   132→  position: fixed;
   133→  top: 0;
   134→  width: 100%;
   135→  height: var(--nav-height);
   136→  background: rgba(255,255,255,0.94);
   137→  backdrop-filter: blur(14px);
   138→  -webkit-backdrop-filter: blur(14px);
   139→  border-bottom: 1px solid var(--color-border);
   140→  z-index: 1000;
   141→  transition: box-shadow var(--transition);
   142→}
   143→.navbar.scrolled { box-shadow: var(--shadow-md); }
   144→
   145→.nav-container {
   146→  max-width: 1080px;
   147→  margin: 0 auto;
   148→  padding: 0 24px;
   149→  height: 100%;
   150→  display: flex;
   151→  align-items: center;
   152→  justify-content: space-between;
   153→}
   154→
   155→.nav-brand {
   156→  display: flex;
   157→  flex-direction: column;
   158→  text-decoration: none;
   159→}
   160→.nav-brand-name {
   161→  font-size: 1.0rem;
   162→  font-weight: 700;
   163→  color: var(--color-text);
   164→  letter-spacing: -0.02em;
   165→  line-height: 1.2;
   166→  transition: color var(--transition);
   167→}
   168→.nav-brand-sub {
   169→  font-size: 0.7rem;
   170→  font-weight: 400;
   171→  color: var(--color-text-muted);
   172→  letter-spacing: 0.02em;
   173→}
   174→.nav-brand:hover .nav-brand-name { color: var(--color-primary); }
   175→
   176→.nav-links {
   177→  list-style: none;
   178→  display: flex;
   179→  gap: 30px;
   180→}
   181→.nav-links a {
   182→  font-size: 0.875rem;
   183→  font-weight: 500;
   184→  color: var(--color-text-muted);
   185→  text-decoration: none;
   186→  transition: color var(--transition);
   187→  position: relative;
   188→}
   189→.nav-links a::after {
   190→  content: '';
   191→  position: absolute;
   192→  bottom: -4px;
   193→  left: 0;
   194→  width: 0;
   195→  height: 2px;
   196→  background: var(--color-primary);
   197→  border-radius: var(--radius-full);
   198→  transition: width var(--transition);
   199→}
   200→.nav-links a:hover,
   201→.nav-links a.active { color: var(--color-primary); }
   202→.nav-links a:hover::after,
   203→.nav-links a.active::after { width: 100%; }
   204→
   205→.nav-toggle {
   206→  display: none;
   207→  flex-direction: column;
   208→  gap: 5px;
   209→  background: none;
   210→  border: none;
   211→  cursor: pointer;
   212→  padding: 4px;
   213→}
   214→.nav-toggle span {
   215→  display: block;
   216→  width: 22px;
   217→  height: 2px;
   218→  background: var(--color-text);
   219→  border-radius: 2px;
   220→  transition: all var(--transition);
   221→}
   222→
   223→/* ---------- Hero ---------- */
   224→.hero {
   225→  min-height: 100vh;
   226→  display: flex;
   227→  flex-direction: column;
   228→  align-items: center;
   229→  justify-content: center;
   230→  padding: calc(var(--nav-height) + 60px) 24px 80px;
   231→  background: linear-gradient(135deg, #f0f9ff 0%, #eff6ff 40%, #f5f3ff 100%);
   232→  position: relative;
   233→  overflow: hidden;
   234→}
   235→
   236→.hero-bg-pattern {
   237→  position: absolute;
   238→  inset: 0;
   239→  background-image:
   240→    radial-gradient(circle at 20% 30%, rgba(29,78,216,0.06) 0%, transparent 50%),
   241→    radial-gradient(circle at 80% 70%, rgba(124,58,237,0.05) 0%, transparent 50%);
   242→  pointer-events: none;
   243→}
   244→
   245→.hero-content {
   246→  display: flex;
   247→  align-items: center;
   248→  gap: 64px;
   249→  max-width: 900px;
   250→  width: 100%;
   251→  position: relative;
   252→}
   253→
   254→.hero-avatar { flex-shrink: 0; position: relative; }
   255→
   256→
   257→.avatar-img {
   258→  width: 160px;
   259→  height: 160px;
   260→  border-radius: 50%;
   261→  object-fit: cover;
   262→  box-shadow: 0 8px 32px rgba(37,99,235,0.3);
   263→  border: 4px solid #fff;
   264→}
   265→
   266→.hero-pre {
   267→  font-size: 0.8rem;
   268→  font-weight: 600;
   269→  text-transform: uppercase;
   270→  letter-spacing: 0.12em;
   271→  color: var(--color-primary);
   272→  margin-bottom: 10px;
   273→}
   274→
   275→.hero-name {
   276→  font-family: var(--font-serif);
   277→  font-size: 2.9rem;
   278→  font-weight: 700;
   279→  line-height: 1.15;
   280→  letter-spacing: -0.03em;
   281→  color: var(--color-text);
   282→  margin-bottom: 14px;
   283→}
   284→
   285→.hero-affiliation {
   286→  display: flex;
   287→  align-items: center;
   288→  gap: 6px;
   289→  font-size: 0.875rem;
   290→  color: var(--color-text-muted);
   291→  margin-bottom: 20px;
   292→  font-weight: 400;
   293→}
   294→.hero-affiliation svg { flex-shrink: 0; color: var(--color-primary); }
   295→
   296→.hero-tags {
   297→  display: flex;
   298→  flex-wrap: wrap;
   299→  gap: 8px;
   300→  margin-bottom: 32px;
   301→}
   302→.hero-tag {
   303→  font-size: 0.75rem;
   304→  font-weight: 500;
   305→  padding: 4px 12px;
   306→  background: rgba(29,78,216,0.08);
   307→  color: var(--color-primary);
   308→  border-radius: var(--radius-full);
   309→  border: 1px solid rgba(29,78,216,0.15);
   310→  letter-spacing: 0.01em;
   311→}
   312→
   313→.hero-links {
   314→  display: flex;
   315→  gap: 12px;
   316→  flex-wrap: wrap;
   317→}
   318→
   319→.scroll-down {
   320→  position: absolute;
   321→  bottom: 32px;
   322→  left: 50%;
   323→  transform: translateX(-50%);
   324→  color: var(--color-text-muted);
   325→  animation: bounce 2.2s ease-in-out infinite;
   326→  transition: color var(--transition);
   327→}
   328→.scroll-down:hover { color: var(--color-primary); text-decoration: none; }
   329→@keyframes bounce {
   330→  0%, 100% { transform: translateX(-50%) translateY(0); }
   331→  50%       { transform: translateX(-50%) translateY(7px); }
   332→}
   333→
   334→/* ---------- Sections ---------- */
   335→.section { padding: 96px 0; }
   336→.section-alt { background: var(--color-bg-alt); }
   337→
   338→.section-title {
   339→  font-family: var(--font-serif);
   340→  font-size: 1.9rem;
   341→  font-weight: 700;
   342→  color: var(--color-text);
   343→  margin-bottom: 12px;
   344→  letter-spacing: -0.02em;
   345→  position: relative;
   346→  display: inline-block;
   347→}
   348→.section-title::after {
   349→  content: '';
   350→  display: block;
   351→  width: 44px;
   352→  height: 4px;
   353→  background: linear-gradient(90deg, var(--color-primary), var(--color-accent));
   354→  border-radius: var(--radius-full);
   355→  margin-top: 10px;
   356→}
   357→
   358→.section-subtitle {
   359→  font-size: 0.97rem;
   360→  color: var(--color-text-muted);
   361→  margin-bottom: 48px;
   362→  max-width: 640px;
   363→  line-height: 1.7;
   364→}
   365→
   366→/* ---------- About ---------- */
   367→.about-grid {
   368→  display: grid;
   369→  grid-template-columns: 1fr 1fr;
   370→  gap: 56px;
   371→  margin-top: 40px;
   372→  align-items: start;
   373→}
   374→
   375→.about-text p {
   376→  margin-bottom: 18px;
   377→  color: var(--color-text);
   378→  font-size: 0.95rem;
   379→  line-height: 1.75;
   380→}
   381→.about-text p:last-child { margin-bottom: 0; }
   382→
   383→.about-highlights {
   384→  display: flex;
   385→  flex-direction: column;
   386→  gap: 16px;
   387→}
   388→
   389→.about-stats {
   390→  display: flex;
   391→  align-items: center;
   392→  background: linear-gradient(135deg, var(--color-primary), var(--color-accent));
   393→  border-radius: var(--radius-md);
   394→  padding: 24px 28px;
   395→  margin-bottom: 4px;
   396→}
   397→
   398→.stat-item {
   399→  flex: 1;
   400→  text-align: center;
   401→}
   402→.stat-number {
   403→  display: block;
   404→  font-size: 2.2rem;
   405→  font-weight: 700;
   406→  color: #fff;
   407→  line-height: 1;
   408→  font-family: var(--font-serif);
   409→  letter-spacing: -0.04em;
   410→}
   411→.stat-label {
   412→  display: block;
   413→  font-size: 0.72rem;
   414→  font-weight: 500;
   415→  color: rgba(255,255,255,0.75);
   416→  text-transform: uppercase;
   417→  letter-spacing: 0.1em;
   418→  margin-top: 5px;
   419→}
   420→.stat-divider {
   421→  width: 1px;
   422→  height: 44px;
   423→  background: rgba(255,255,255,0.25);
   424→  flex-shrink: 0;
   425→}
   426→
   427→.highlight-card {
   428→  display: flex;
   429→  align-items: flex-start;
   430→  gap: 16px;
   431→  background: var(--color-card-bg);
   432→  border: 1px solid var(--color-border);
   433→  border-radius: var(--radius-md);
   434→  padding: 18px 20px;
   435→  box-shadow: var(--shadow-sm);
   436→  transition: box-shadow var(--transition), transform var(--transition);
   437→}
   438→.highlight-card:hover {
   439→  box-shadow: var(--shadow-md);
   440→  transform: translateY(-2px);
   441→}
   442→
   443→.highlight-icon-wrap {
   444→  width: 42px;
   445→  height: 42px;
   446→  flex-shrink: 0;
   447→  background: var(--color-primary-light);
   448→  border-radius: var(--radius-sm);
   449→  display: flex;
   450→  align-items: center;
   451→  justify-content: center;
   452→  color: var(--color-primary);
   453→}
   454→
   455→.highlight-card h3 {
   456→  font-size: 0.9rem;
   457→  font-weight: 600;
   458→  margin-bottom: 4px;
   459→  color: var(--color-text);
   460→}
   461→.highlight-card p {
   462→  font-size: 0.835rem;
   463→  color: var(--color-text-muted);
   464→  line-height: 1.55;
   465→}
   466→
   467→/* ---------- Research Interests ---------- */
   468→.interests-grid {
   469→  display: grid;
   470→  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
   471→  gap: 22px;
   472→  margin-top: 40px;
   473→}
   474→
   475→.interest-card {
   476→  background: var(--color-card-bg);
   477→  border: 1px solid var(--color-border);
   478→  border-top: 3px solid var(--color-primary);
   479→  border-radius: var(--radius-md);
   480→  padding: 28px 24px 24px;
   481→  box-shadow: var(--shadow-sm);
   482→  transition: box-shadow var(--transition), transform var(--transition);
   483→}
   484→.interest-card:hover {
   485→  box-shadow: var(--shadow-md);
   486→  transform: translateY(-4px);
   487→}
   488→
   489→.interest-icon-wrap {
   490→  width: 56px;
   491→  height: 56px;
   492→  display: flex;
   493→  align-items: center;
   494→  justify-content: center;
   495→  background: var(--color-primary-light);
   496→  border-radius: var(--radius-md);
   497→  color: var(--color-primary);
   498→  margin-bottom: 18px;
   499→}
   500→
   501→.interest-card h3 {
   502→  font-size: 0.95rem;
   503→  font-weight: 600;
   504→  margin-bottom: 10px;
   505→  color: var(--color-text);
   506→}
   507→.interest-card p {
   508→  font-size: 0.855rem;
   509→  color: var(--color-text-muted);
   510→  line-height: 1.65;
   511→}
   512→
   513→/* ---------- Publications ---------- */
   514→.pub-year-group {
   515→  margin-bottom: 40px;
   516→}
   517→
   518→.pub-year-label {
   519→  font-family: var(--font-serif);
   520→  font-size: 1.15rem;
   521→  font-weight: 700;
   522→  color: var(--color-text);
   523→  padding-bottom: 10px;
   524→  border-bottom: 2px solid var(--color-border);
   525→  margin-bottom: 16px;
   526→  letter-spacing: -0.01em;
   527→  display: flex;
   528→  align-items: center;
   529→  gap: 12px;
   530→}
   531→.pub-year-label::after {
   532→  content: '';
   533→  flex: 1;
   534→  height: 2px;
   535→  background: var(--color-border);
   536→  display: none;
   537→}
   538→
   539→.publications-list {
   540→  display: flex;
   541→  flex-direction: column;
   542→  gap: 14px;
   543→}
   544→
   545→.publication-card {
   546→  background: var(--color-card-bg);
   547→  border: 1px solid var(--color-border);
   548→  border-left: 4px solid var(--color-primary);
   549→  border-radius: var(--radius-md);
   550→  padding: 20px 24px;
   551→  box-shadow: var(--shadow-sm);
