/* =====================================================
   Personal Portfolio – Samson Tilahun Moges
   ===================================================== */

/* ---------- CSS Custom Properties ---------- */
:root {
  --color-primary:       #1d4ed8;
  --color-primary-dark:  #1e40af;
  --color-primary-light: #eff6ff;
  --color-accent:        #7c3aed;
  --color-accent-light:  #f5f3ff;

  --color-bg:            #ffffff;
  --color-bg-alt:        #f8fafc;
  --color-bg-dark:       #0f172a;

  --color-text:          #0f172a;
  --color-text-muted:    #64748b;
  --color-text-light:    #94a3b8;

  --color-border:        #e2e8f0;
  --color-card-bg:       #ffffff;

  /* publication quality colours */
  --color-q1:            #065f46;
  --color-q1-bg:         #d1fae5;
  --color-q2:            #1e40af;
  --color-q2-bg:         #dbeafe;
  --color-thesis:        #6b21a8;
  --color-thesis-bg:     #f3e8ff;
  --color-conf:          #92400e;
  --color-conf-bg:       #fef3c7;
  --color-preprint:      #be185d;
  --color-preprint-bg:   #fce7f3;

  --font-sans:  'Inter', system-ui, -apple-system, sans-serif;
  --font-serif: 'Merriweather', Georgia, 'Times New Roman', serif;

  --radius-sm:   6px;
  --radius-md:   12px;
  --radius-lg:   20px;
  --radius-full: 9999px;

  --shadow-sm:  0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md:  0 4px 16px rgba(0,0,0,0.08), 0 2px 6px rgba(0,0,0,0.05);
  --shadow-lg:  0 10px 40px rgba(0,0,0,0.10), 0 4px 12px rgba(0,0,0,0.06);

  --transition: 0.22s ease;
  --nav-height: 68px;
}

/* ---------- Reset & Base ---------- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img { max-width: 100%; display: block; }
a  { color: var(--color-primary); text-decoration: none; }
a:hover { text-decoration: underline; }

/* ---------- Utilities ---------- */
.container {
  max-width: 1080px;
  margin: 0 auto;
  padding: 0 24px;
}

.inline-link {
  color: var(--color-primary);
  font-weight: 500;
  border-bottom: 1px solid transparent;
  transition: border-color var(--transition);
}
.inline-link:hover { text-decoration: none; border-bottom-color: var(--color-primary); }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 10px 22px;
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition), color var(--transition),
              border-color var(--transition), transform var(--transition),
              box-shadow var(--transition);
  border: 2px solid transparent;
  text-decoration: none !important;
  white-space: nowrap;

