/* =====================================================
   Personal Portfolio – Samson Tilahun Moges
   ===================================================== */

/* ---------- CSS Custom Properties ---------- */
:root {
  --color-primary:       #1d4ed8;
  --color-primary-dark:  #1e40af;
  --color-primary-light: #eff6ff;
  --color-accent:        #7c3aed;
  --color-accent-light:  #f5f3ff;

  --color-bg:            #ffffff;
  --color-bg-alt:        #f8fafc;
  --color-bg-dark:       #0f172a;

  --color-text:          #0f172a;
  --color-text-muted:    #64748b;
  --color-text-light:    #94a3b8;

  --color-border:        #e2e8f0;
  --color-card-bg:       #ffffff;

  /* publication quality colours */
  --color-q1:            #065f46;
  --color-q1-bg:         #d1fae5;
  --color-q2:            #1e40af;
  --color-q2-bg:         #dbeafe;
  --color-thesis:        #6b21a8;
  --color-thesis-bg:     #f3e8ff;
  --color-conf:          #92400e;
  --color-conf-bg:       #fef3c7;
  --color-preprint:      #be185d;
  --color-preprint-bg:   #fce7f3;

  --font-sans:  'Inter', system-ui, -apple-system, sans-serif;
  --font-serif: 'Merriweather', Georgia, 'Times New Roman', serif;

  --radius-sm:   6px;
  --radius-md:   12px;
  --radius-lg:   20px;
  --radius-full: 9999px;

  --shadow-sm:  0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md:  0 4px 16px rgba(0,0,0,0.08), 0 2px 6px rgba(0,0,0,0.05);
  --shadow-lg:  0 10px 40px rgba(0,0,0,0.10), 0 4px 12px rgba(0,0,0,0.06);

  --transition: 0.22s ease;
  --nav-height: 68px;
}

/* ---------- Reset & Base ---------- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img { max-width: 100%; display: block; }
a  { color: var(--color-primary); text-decoration: none; }
a:hover { text-decoration: underline; }

/* ---------- Utilities ---------- */
.container {
  max-width: 1080px;
  margin: 0 auto;
  padding: 0 24px;
}

.inline-link {
  color: var(--color-primary);
  font-weight: 500;
  border-bottom: 1px solid transparent;
  transition: border-color var(--transition);
}
.inline-link:hover { text-decoration: none; border-bottom-color: var(--color-primary); }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 10px 22px;
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition), color var(--transition),
              border-color var(--transition), transform var(--transition),
              box-shadow var(--transition);
  border: 2px solid transparent;
  text-decoration: none !important;
  white-space: nowrap;
  letter-spacing: 0.01em;
}
.btn:active { transform: scale(0.97); }

.btn-primary {
  background: var(--color-primary);
  color: #fff;
  border-color: var(--color-primary);
}
.btn-primary:hover {
  background: var(--color-primary-dark);
  border-color: var(--color-primary-dark);
  box-shadow: 0 4px 18px rgba(29,78,216,0.35);
}

.btn-outline {
  background: transparent;
  color: var(--color-primary);
  border-color: var(--color-primary);
}
.btn-outline:hover {
  background: var(--color-primary);
  color: #fff;
  box-shadow: 0 4px 14px rgba(29,78,216,0.25);
}

.btn-sm   { padding: 5px 14px; font-size: 0.8rem; }
.btn-large { padding: 14px 34px; font-size: 0.95rem; }

/* ---------- Navbar ---------- */
.navbar {
  position: fixed;
  top: 0;
  width: 100%;
  height: var(--nav-height);
  background: rgba(255,255,255,0.94);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--color-border);
  z-index: 1000;
  transition: box-shadow var(--transition);
}
.navbar.scrolled { box-shadow: var(--shadow-md); }

.nav-container {
  max-width: 1080px;
  margin: 0 auto;
  padding: 0 24px;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nav-brand {
  display: flex;
  flex-direction: column;
  text-decoration: none;
}
.nav-brand-name {
  font-size: 1.0rem;
  font-weight: 700;
  color: var(--color-text);
  letter-spacing: -0.02em;
  line-height: 1.2;
  transition: color var(--transition);
}
.nav-brand-sub {
  font-size: 0.7rem;
  font-weight: 400;
  color: var(--color-text-muted);
  letter-spacing: 0.02em;
}
.nav-brand:hover .nav-brand-name { color: var(--color-primary); }

.nav-links {
  list-style: none;
  display: flex;
  gap: 30px;
}
.nav-links a {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-muted);
  text-decoration: none;
  transition: color var(--transition);
  position: relative;
}
.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--color-primary);
  border-radius: var(--radius-full);
  transition: width var(--transition);
}
.nav-links a:hover,
.nav-links a.active { color: var(--color-primary); }
.nav-links a:hover::after,
.nav-links a.active::after { width: 100%; }

.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
}
.nav-toggle span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--color-text);
  border-radius: 2px;
  transition: all var(--transition);
}

/* ---------- Hero ---------- */
.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: calc(var(--nav-height) + 60px) 24px 80px;
  background: linear-gradient(135deg, #f0f9ff 0%, #eff6ff 40%, #f5f3ff 100%);
  position: relative;
  overflow: hidden;
}

.hero-bg-pattern {
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 20% 30%, rgba(29,78,216,0.06) 0%, transparent 50%),
    radial-gradient(circle at 80% 70%, rgba(124,58,237,0.05) 0%, transparent 50%);
  pointer-events: none;
}

.hero-content {
  display: flex;
  align-items: center;
  gap: 64px;
  max-width: 900px;
  width: 100%;
  position: relative;
}

.hero-avatar { flex-shrink: 0; position: relative; }


.avatar-img {
  width: 160px;
  height: 160px;
  border-radius: 50%;
  object-fit: cover;
  box-shadow: 0 8px 32px rgba(37,99,235,0.3);
  border: 4px solid #fff;
}

.hero-pre {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--color-primary);
  margin-bottom: 10px;
}

.hero-name {
  font-family: var(--font-serif);
  font-size: 2.9rem;
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.03em;
  color: var(--color-text);
  margin-bottom: 14px;
}

.hero-affiliation {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.875rem;
  color: var(--color-text-muted);
  margin-bottom: 20px;
  font-weight: 400;
}
.hero-affiliation svg { flex-shrink: 0; color: var(--color-primary); }

.hero-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 32px;
}
.hero-tag {
  font-size: 0.75rem;
  font-weight: 500;
  padding: 4px 12px;
  background: rgba(29,78,216,0.08);
  color: var(--color-primary);
  border-radius: var(--radius-full);
  border: 1px solid rgba(29,78,216,0.15);
  letter-spacing: 0.01em;
}

.hero-links {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.scroll-down {
  position: absolute;
  bottom: 32px;
  left: 50%;
  transform: translateX(-50%);
  color: var(--color-text-muted);
  animation: bounce 2.2s ease-in-out infinite;
  transition: color var(--transition);
}
.scroll-down:hover { color: var(--color-primary); text-decoration: none; }
@keyframes bounce {
  0%, 100% { transform: translateX(-50%) translateY(0); }
  50%       { transform: translateX(-50%) translateY(7px); }
}

/* ---------- Sections ---------- */
.section { padding: 96px 0; }
.section-alt { background: var(--color-bg-alt); }

.section-title {
  font-family: var(--font-serif);
  font-size: 1.9rem;
  font-weight: 700;
  color: var(--color-text);
  margin-bottom: 12px;
  letter-spacing: -0.02em;
  position: relative;
  display: inline-block;
}
.section-title::after {
  content: '';
  display: block;
  width: 44px;
  height: 4px;
  background: linear-gradient(90deg, var(--color-primary), var(--color-accent));
  border-radius: var(--radius-full);
  margin-top: 10px;
}

.section-subtitle {
  font-size: 0.97rem;
  color: var(--color-text-muted);
  margin-bottom: 48px;
  max-width: 640px;
  line-height: 1.7;
}

/* ---------- About ---------- */
.about-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 56px;
  margin-top: 40px;
  align-items: start;
}

.about-text p {
  margin-bottom: 18px;
  color: var(--color-text);
  font-size: 0.95rem;
  line-height: 1.75;
}
.about-text p:last-child { margin-bottom: 0; }

.about-highlights {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.about-stats {
  display: flex;
  align-items: center;
  background: linear-gradient(135deg, var(--color-primary), var(--color-accent));
  border-radius: var(--radius-md);
  padding: 24px 28px;
  margin-bottom: 4px;
}

.stat-item {
  flex: 1;
  text-align: center;
}
.stat-number {
  display: block;
  font-size: 2.2rem;
  font-weight: 700;
  color: #fff;
  line-height: 1;
  font-family: var(--font-serif);
  letter-spacing: -0.04em;
}
.stat-label {
  display: block;
  font-size: 0.72rem;
  font-weight: 500;
  color: rgba(255,255,255,0.75);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-top: 5px;
}
.stat-divider {
  width: 1px;
  height: 44px;
  background: rgba(255,255,255,0.25);
  flex-shrink: 0;
}

.highlight-card {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  background: var(--color-card-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 18px 20px;
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition), transform var(--transition);
}
.highlight-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.highlight-icon-wrap {
  width: 42px;
  height: 42px;
  flex-shrink: 0;
  background: var(--color-primary-light);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-primary);
}

.highlight-card h3 {
  font-size: 0.9rem;
  font-weight: 600;
  margin-bottom: 4px;
  color: var(--color-text);
}
.highlight-card p {
  font-size: 0.835rem;
  color: var(--color-text-muted);
  line-height: 1.55;
}

/* ---------- Research Interests ---------- */
.interests-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 22px;
  margin-top: 40px;
}

.interest-card {
  background: var(--color-card-bg);
  border: 1px solid var(--color-border);
  border-top: 3px solid var(--color-primary);
  border-radius: var(--radius-md);
  padding: 28px 24px 24px;
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition), transform var(--transition);
}
.interest-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.interest-icon-wrap {
  width: 56px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--color-primary-light);
  border-radius: var(--radius-md);
  color: var(--color-primary);
  margin-bottom: 18px;
}

.interest-card h3 {
  font-size: 0.95rem;
  font-weight: 600;
  margin-bottom: 10px;
  color: var(--color-text);
}
.interest-card p {
  font-size: 0.855rem;
  color: var(--color-text-muted);
  line-height: 1.65;
}

/* ---------- Publications ---------- */
.pub-year-group {
  margin-bottom: 40px;
}

.pub-year-label {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--color-text);
  padding-bottom: 10px;
  border-bottom: 2px solid var(--color-border);
  margin-bottom: 16px;
  letter-spacing: -0.01em;
  display: flex;
  align-items: center;
  gap: 12px;
}
.pub-year-label::after {
