.pub-meta-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
  margin-bottom: 9px;
}

.pub-badge {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 700;
  padding: 2px 9px;
  border-radius: var(--radius-full);
  text-transform: uppercase;
  letter-spacing: 0.07em;
}
.pub-badge-journal  { background: #dbeafe; color: #1e40af; }
.pub-badge-conf     { background: #fef3c7; color: #92400e; }
.pub-badge-preprint { background: #fce7f3; color: #be185d; }
.pub-badge-thesis   { background: #f3e8ff; color: #6b21a8; }

.pub-quality {
  display: inline-block;
  font-size: 0.68rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  letter-spacing: 0.05em;
}
.pub-q1 { background: var(--color-q1-bg); color: var(--color-q1); }
.pub-q2 { background: var(--color-q2-bg); color: var(--color-q2); }

.pub-cites {
  font-size: 0.72rem;
  color: var(--color-text-muted);
  font-weight: 500;
  margin-left: auto;
}

.pub-title {
  font-size: 0.975rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 6px;
  line-height: 1.5;
}

.pub-authors {
  font-size: 0.845rem;
  color: var(--color-text-muted);
  margin-bottom: 3px;
}
.pub-authors strong { color: var(--color-text); font-weight: 600; }

.pub-venue {
  font-size: 0.845rem;
  color: var(--color-text-muted);
  margin-bottom: 12px;
}

.scholar-cta {
  text-align: center;
  margin-top: 40px;
  padding-top: 32px;
  border-top: 1px solid var(--color-border);
}

/* ---------- Contact ---------- */
.contact-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 20px;
  margin-top: 40px;
}

.contact-card {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  background: var(--color-card-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 22px 20px;
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition), transform var(--transition);
}
.contact-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}

.contact-icon {
  width: 44px;
  height: 44px;
  flex-shrink: 0;
  background: var(--color-primary-light);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-primary);
}

.contact-card h3 {
  font-size: 0.9rem;
  font-weight: 600;
  margin-bottom: 4px;
  color: var(--color-text);
}
.contact-card p,
.contact-card a {
  font-size: 0.845rem;
  color: var(--color-text-muted);
  line-height: 1.5;
}

/* ---------- Footer ---------- */
.footer {
  background: var(--color-bg-dark);
  color: rgba(255,255,255,0.55);
  padding: 32px 0;
  text-align: center;
}
.footer .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}
.footer p { font-size: 0.84rem; }
.footer-links {
  display: flex;
  gap: 22px;
}
.footer-links a {
  font-size: 0.84rem;
  color: rgba(255,255,255,0.55);
  transition: color var(--transition);
}
.footer-links a:hover { color: #fff; text-decoration: none; }

