    76→  --color-q1:            #006b60;
    77→  --color-q1-bg:         rgba(0, 107, 96, 0.10);
    78→  --color-q2:            #1d4ed8;
    79→  --color-q2-bg:         rgba(29, 78, 216, 0.10);
    80→  --color-thesis:        #7c3aed;
    81→  --color-thesis-bg:     rgba(124, 58, 237, 0.10);
    82→  --color-conf:          #92400e;
    83→  --color-conf-bg:       rgba(146, 64, 14, 0.10);
    84→  --color-preprint:      #be185d;
    85→  --color-preprint-bg:   rgba(190, 24, 93, 0.10);
    86→}
    87→
    88→/* ---------- Fonts ---------- */
    89→:root {
    90→  --font-display: 'Playfair Display', Georgia, 'Times New Roman', serif;
    91→  --font-sans:    'Source Sans 3', 'Helvetica Neue', system-ui, sans-serif;
    92→  --font-mono:    'JetBrains Mono', 'Fira Code', Consolas, monospace;
    93→
    94→  --radius-xs:   4px;
    95→  --radius-sm:   8px;
    96→  --radius-md:   14px;
    97→  --radius-lg:   22px;
    98→  --radius-xl:   32px;
    99→  --radius-full: 9999px;
   100→
   101→  --shadow-sm:  0 2px 8px rgba(0,0,0,0.12);
   102→  --shadow-md:  0 8px 32px rgba(0,0,0,0.18), 0 2px 8px rgba(0,0,0,0.12);
   103→  --shadow-lg:  0 20px 60px rgba(0,0,0,0.28), 0 6px 20px rgba(0,0,0,0.16);
   104→  --shadow-glow: 0 0 40px rgba(0, 200, 180, 0.18);
   105→
   106→  --transition: 0.22s ease;
   107→  --transition-slow: 0.4s ease;
   108→}
   109→
   110→[data-theme="light"] {
   111→  --shadow-sm:  0 2px 8px rgba(0,0,0,0.06);
   112→  --shadow-md:  0 8px 32px rgba(0,0,0,0.10), 0 2px 8px rgba(0,0,0,0.06);
   113→  --shadow-lg:  0 20px 60px rgba(0,0,0,0.12), 0 6px 20px rgba(0,0,0,0.08);
   114→  --shadow-glow: 0 0 40px rgba(0, 125, 114, 0.15);
   115→}
   116→
   117→/* ---------- Reset & Base ---------- */
   118→*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
   119→
   120→html {
   121→  scroll-behavior: smooth;
   122→  font-size: 16px;
   123→  -webkit-text-size-adjust: 100%;
   124→}
   125→
   126→body {
   127→  font-family: var(--font-sans);
   128→  color: var(--color-text);
   129→  background: var(--color-bg);
   130→  line-height: 1.7;
   131→  -webkit-font-smoothing: antialiased;
   132→  -moz-osx-font-smoothing: grayscale;
   133→  transition: background var(--transition-slow), color var(--transition-slow);
   134→  overflow-x: hidden;
   135→}
   136→
   137→img { max-width: 100%; display: block; }
   138→a  { color: var(--color-primary); text-decoration: none; }
   139→a:hover { text-decoration: underline; }
   140→button { cursor: pointer; font-family: var(--font-sans); }
   141→
   142→/* ---------- Scroll Progress Bar ---------- */
   143→#scroll-progress {
   144→  position: fixed;
   145→  top: 0;
   146→  left: 0;
   147→  height: 3px;
   148→  width: 0%;
   149→  background: linear-gradient(90deg, var(--color-primary), var(--color-accent));
   150→  z-index: 9999;
   151→  transition: width 0.1s linear;
   152→  border-radius: 0 var(--radius-full) var(--radius-full) 0;
   153→}
   154→
   155→/* ---------- Utilities ---------- */
   156→.container {
   157→  max-width: 1100px;
   158→  margin: 0 auto;
   159→  padding: 0 28px;
   160→}
   161→
   162→.inline-link {
   163→  color: var(--color-primary);
   164→  font-weight: 500;
   165→  border-bottom: 1px solid transparent;
   166→  transition: border-color var(--transition);
   167→}
   168→.inline-link:hover { text-decoration: none; border-bottom-color: var(--color-primary); }
   169→
   170→/* ---------- Buttons ---------- */
   171→.btn {
   172→  display: inline-flex;
   173→  align-items: center;
   174→  gap: 7px;
   175→  padding: 10px 22px;
   176→  border-radius: var(--radius-full);
   177→  font-size: 0.875rem;
   178→  font-weight: 600;
   179→  font-family: var(--font-sans);
   180→  cursor: pointer;
   181→  transition: all var(--transition);
   182→  border: 2px solid transparent;
   183→  text-decoration: none !important;
   184→  white-space: nowrap;
   185→  letter-spacing: 0.01em;
   186→}
   187→.btn:hover { transform: translateY(-2px); text-decoration: none; }
   188→.btn:active { transform: translateY(0); }
   189→
   190→.btn-primary {
   191→  background: var(--color-primary);
   192→  color: #050c1a;
   193→  border-color: var(--color-primary);
   194→}
   195→[data-theme="light"] .btn-primary { color: #ffffff; }
   196→.btn-primary:hover { background: var(--color-primary-dark); border-color: var(--color-primary-dark); box-shadow: 0 4px 20px rgba(0, 200, 180, 0.35); }
   197→
   198→.btn-outline {
   199→  background: transparent;
   200→  color: var(--color-primary);
   201→  border-color: var(--color-primary);
   202→}
   203→.btn-outline:hover { background: var(--color-primary-light); }
   204→
   205→.btn-ghost {
   206→  background: var(--color-surface-2);
   207→  color: var(--color-text-muted);
   208→  border-color: var(--color-border);
   209→}
   210→.btn-ghost:hover { background: var(--color-surface-3); color: var(--color-text); }
   211→
   212→.btn-accent {
   213→  background: var(--color-accent);
   214→  color: #050c1a;
   215→  border-color: var(--color-accent);
   216→}
   217→[data-theme="light"] .btn-accent { color: #ffffff; }
   218→.btn-accent:hover { background: var(--color-accent-dark); border-color: var(--color-accent-dark); }
   219→
   220→.btn-sm {
   221→  padding: 6px 14px;
   222→  font-size: 0.8rem;
   223→}
   224→
   225→.btn-large {
   226→  padding: 13px 30px;
   227→  font-size: 0.95rem;
   228→}
   229→
   230→/* ---------- Sections ---------- */
   231→.section {
   232→  padding: 100px 0;
   233→}
   234→.section-alt {
   235→  background: var(--color-bg-alt);
   236→}
   237→
   238→.section-title {
   239→  font-family: var(--font-display);
   240→  font-size: clamp(1.8rem, 3vw, 2.6rem);
   241→  font-weight: 700;
   242→  color: var(--color-text);
   243→  margin-bottom: 12px;
   244→  letter-spacing: -0.01em;
   245→  line-height: 1.2;
   246→}
   247→.section-title::after {
   248→  content: '';
   249→  display: block;
   250→  width: 48px;
   251→  height: 3px;
   252→  background: linear-gradient(90deg, var(--color-primary), var(--color-accent));
   253→  margin-top: 12px;
   254→  border-radius: var(--radius-full);
   255→}
   256→
   257→.section-subtitle {
   258→  font-size: 1.05rem;
   259→  color: var(--color-text-muted);
   260→  margin-bottom: 56px;
   261→  max-width: 640px;
   262→  line-height: 1.65;
   263→}
   264→
   265→.subsection-title {
   266→  font-family: var(--font-display);
   267→  font-size: 1.4rem;
   268→  font-weight: 600;
   269→  color: var(--color-text);
   270→  margin: 64px 0 28px;
   271→}
   272→
   273→/* ---------- Fade-in animation ---------- */
   274→.fade-in {
   275→  opacity: 0;
   276→  transform: translateY(24px);
   277→  transition: opacity 0.55s ease, transform 0.55s ease;
   278→}
   279→.fade-in.visible {
   280→  opacity: 1;
   281→  transform: translateY(0);
   282→}
   283→
   284→/* =====================================================
   285→   NAVBAR
   286→   ===================================================== */
   287→.navbar {
   288→  position: fixed;
   289→  top: 0;
   290→  left: 0;
   291→  right: 0;
   292→  z-index: 1000;
   293→  height: var(--nav-height);
   294→  transition: background var(--transition), box-shadow var(--transition), backdrop-filter var(--transition);
   295→}
   296→.navbar.scrolled {
   297→  background: rgba(5, 12, 26, 0.85);
   298→  backdrop-filter: blur(16px);
   299→  -webkit-backdrop-filter: blur(16px);
   300→  box-shadow: 0 1px 0 var(--color-border), 0 4px 24px rgba(0,0,0,0.3);
   301→}
   302→[data-theme="light"] .navbar.scrolled {
   303→  background: rgba(248, 251, 255, 0.88);
   304→  box-shadow: 0 1px 0 var(--color-border), 0 4px 24px rgba(0,0,0,0.08);
   305→}
   306→
   307→.nav-container {
   308→  max-width: 1200px;
   309→  margin: 0 auto;
   310→  padding: 0 28px;
   311→  height: 100%;
   312→  display: flex;
   313→  align-items: center;
   314→  justify-content: space-between;
   315→  gap: 16px;
   316→}
   317→
   318→.nav-brand {
   319→  display: flex;
   320→  flex-direction: column;
   321→  line-height: 1.2;
   322→  text-decoration: none;
   323→  flex-shrink: 0;
   324→}
   325→.nav-brand:hover { text-decoration: none; }
   326→.nav-brand-name {
   327→  font-family: var(--font-display);
   328→  font-size: 1.05rem;
   329→  font-weight: 700;
   330→  color: var(--color-text);
   331→  letter-spacing: -0.01em;
   332→}
   333→.nav-brand-sub {
   334→  font-size: 0.7rem;
   335→  font-weight: 500;
   336→  color: var(--color-primary);
   337→  letter-spacing: 0.05em;
   338→  text-transform: uppercase;
   339→}
   340→
   341→.nav-right {
   342→  display: flex;
   343→  align-items: center;
   344→  gap: 8px;
   345→}
   346→
   347→.nav-links {
   348→  display: flex;
   349→  align-items: center;
   350→  list-style: none;
   351→  gap: 2px;
   352→}
   353→.nav-links a {
   354→  display: block;
   355→  padding: 6px 12px;
   356→  font-size: 0.875rem;
   357→  font-weight: 500;
   358→  color: var(--color-text-muted);
   359→  border-radius: var(--radius-sm);
   360→  transition: color var(--transition), background var(--transition);
   361→  text-decoration: none;
   362→  letter-spacing: 0.01em;
   363→}
   364→.nav-links a:hover,
   365→.nav-links a.active {
   366→  color: var(--color-primary);
   367→  background: var(--color-primary-light);
   368→  text-decoration: none;
   369→}
   370→
   371→/* Theme Toggle */
   372→.theme-toggle {
   373→  display: flex;
   374→  align-items: center;
   375→  justify-content: center;
   376→  width: 38px;
   377→  height: 38px;
   378→  border-radius: var(--radius-full);
   379→  border: 1px solid var(--color-border);
   380→  background: var(--color-surface-2);
   381→  color: var(--color-text-muted);
   382→  transition: all var(--transition);
   383→  flex-shrink: 0;
   384→}
   385→.theme-toggle:hover {
   386→  background: var(--color-surface-3);
   387→  color: var(--color-primary);
   388→  border-color: var(--color-primary);
   389→}
   390→.icon-sun  { display: none; }
   391→.icon-moon { display: block; }
   392→[data-theme="light"] .icon-sun  { display: block; }
   393→[data-theme="light"] .icon-moon { display: none; }
   394→
   395→/* Mobile nav toggle */
   396→.nav-toggle {
   397→  display: none;
   398→  flex-direction: column;
   399→  justify-content: space-between;
   400→  width: 24px;
   401→  height: 18px;
   402→  background: transparent;
   403→  border: none;
   404→  padding: 0;
   405→  cursor: pointer;
   406→}
   407→.nav-toggle span {
   408→  display: block;
   409→  height: 2px;
   410→  background: var(--color-text-muted);
   411→  border-radius: 2px;
   412→  transition: all var(--transition);
   413→}
   414→
   415→/* =====================================================
   416→   HERO
   417→   ===================================================== */
   418→.hero {
   419→  position: relative;
   420→  min-height: 100vh;
   421→  display: flex;
   422→  align-items: center;
   423→  justify-content: center;
   424→  overflow: hidden;
   425→  background: linear-gradient(180deg, #020913 0%, #050c1a 30%, #070f20 60%, #0a1628 100%);
   426→  padding-top: var(--nav-height);
   427→}
   428→
   429→[data-theme="light"] .hero {
   430→  background: linear-gradient(180deg, #e8f1fd 0%, #d8eafa 30%, #cee3f8 60%, #c5dcf5 100%);
   431→}
   432→
   433→/* Aurora Background */
   434→.hero-aurora {
   435→  position: absolute;
   436→  inset: 0;
   437→  pointer-events: none;
   438→  overflow: hidden;
   439→}
   440→.aurora-1, .aurora-2, .aurora-3 {
   441→  position: absolute;
   442→  inset: -60%;
   443→  border-radius: 50%;
   444→}
   445→.aurora-1 {
   446→  background: radial-gradient(
   447→    ellipse 100% 50% at 25% 55%,
   448→    rgba(0, 200, 180, 0.22) 0%,
   449→    rgba(0, 150, 140, 0.08) 45%,
   450→    transparent 70%
   451→  );
   452→  animation: auroraFloat1 20s ease-in-out infinite alternate;
   453→}
   454→.aurora-2 {
   455→  background: radial-gradient(
   456→    ellipse 80% 60% at 70% 45%,
   457→    rgba(100, 30, 200, 0.18) 0%,
   458→    rgba(80, 20, 160, 0.07) 45%,
   459→    transparent 70%
   460→  );
   461→  animation: auroraFloat2 26s ease-in-out infinite alternate;
   462→}
   463→.aurora-3 {
   464→  background: radial-gradient(
   465→    ellipse 70% 80% at 50% 85%,
   466→    rgba(20, 60, 180, 0.15) 0%,
   467→    transparent 60%
   468→  );
   469→  animation: auroraFloat3 16s ease-in-out infinite alternate;
   470→}
   471→
   472→[data-theme="light"] .aurora-1 {
   473→  background: radial-gradient(
   474→    ellipse 100% 50% at 25% 55%,
   475→    rgba(0, 160, 145, 0.20) 0%,
   476→    rgba(0, 120, 110, 0.06) 45%,
   477→    transparent 70%
   478→  );
   479→}
   480→[data-theme="light"] .aurora-2 {
   481→  background: radial-gradient(
   482→    ellipse 80% 60% at 70% 45%,
   483→    rgba(90, 30, 180, 0.13) 0%,
   484→    transparent 70%
   485→  );
   486→}
   487→[data-theme="light"] .aurora-3 {
   488→  background: radial-gradient(
   489→    ellipse 70% 80% at 50% 85%,
   490→    rgba(10, 50, 160, 0.12) 0%,
   491→    transparent 60%
   492→  );
   493→}
   494→
   495→@keyframes auroraFloat1 {
   496→  from { transform: translate(0, 0) scale(1); }
   497→  to   { transform: translate(8%, -6%) scale(1.2); }
   498→}
   499→@keyframes auroraFloat2 {
   500→  from { transform: translate(0, 0) scale(1) rotate(0deg); }

