/* =====================================================
   SKILLS REDESIGN — categorised cards + language strip
   ===================================================== */
.skills-redesign { margin-top: 48px; }

.skills-redesign-title {
  font-family: var(--font-display);
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 18px;
  display: flex;
  align-items: center;
  gap: 12px;
}
.skills-redesign-title::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--color-border);
}

.skill-cats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.skill-cat {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-left: 3px solid var(--cat-color, var(--color-primary));
  border-radius: var(--radius-md);
  padding: 18px 20px;
  transition: box-shadow var(--transition);
}
.skill-cat:hover { box-shadow: var(--shadow-md); }

.skill-cat--eo   { --cat-color: var(--color-primary); }
.skill-cat--cv   { --cat-color: var(--color-accent); }
